    return targets


def _probe_values(env, sql, schema, budget):
    """For each string literal in the draft, show what the column really stores."""
    lits = [v for v in dict.fromkeys(LITERAL.findall(sql)) if v.strip()]
    if not lits:
        return [], budget
    aliases = _table_aliases(sql)
    schema_cols = _schema_columns(schema)
    targets = _literal_targets(sql, aliases, schema_cols)
    notes = []
    for val in lits:
        if budget <= 0:
            break
        cands = targets.get(val) or []
        core = re.sub(r"[%_]", "", val).strip()
        if not core:
            continue
        for tbl, col in cands[:2]:
            if budget <= 0:
                break
            frag = core.split()[0] if core.split() else core
            probe = (
                f'SELECT DISTINCT "{col}" FROM "{tbl}" '
                f"WHERE \"{col}\" LIKE '%{frag}%' LIMIT 8"
            )
            r = _safe_execute(env, probe, max_rows=8)
            budget -= 1
            if not r.get("ok"):
                continue
            vals = [row[0] for row in r.get("rows", []) if row]
            exact = any(isinstance(v, str) and v == val for v in vals)
            if exact and len(vals) == 1:
                continue
            shown = ", ".join(repr(v) for v in vals[:8]) if vals else "(no similar value found)"
            notes.append(
                f"- Column {tbl}.{col}: you filtered on {val!r}. Values actually stored that look related: {shown}."
            )
            break
    return notes, budget


def _probe_empty_join(env, sql, budget):
    """When a join returns nothing, show sample rows of the joined tables."""
    notes = []
    aliases = _table_aliases(sql)
    tables = list(dict.fromkeys(aliases.values()))
    if len(tables) < 2:
        return notes, budget
    for tbl in tables[:3]:
        if budget <= 0:
            break
        r = _safe_execute(env, f'SELECT * FROM "{tbl}" LIMIT 3', max_rows=3)
        budget -= 1
        if r.get("ok") and r.get("rows"):
            cols = ", ".join(str(c) for c in r.get("columns", []))
            rows = "; ".join(str(row) for row in r["rows"][:3])
            notes.append(f"- Sample rows of {tbl} ({cols}): {rows}")
    return notes, budget


def _subquery_spans(sql):
    """Text of each parenthesised group that starts with SELECT (best effort)."""
    spans = []
    low = sql.lower()
    for m in re.finditer(r"\(\s*select\b", low):
        i = m.start()
        depth = 0
        for j in range(i, len(sql)):
            if sql[j] == "(":
                depth += 1
            elif sql[j] == ")":
                depth -= 1
                if depth == 0:
                    spans.append(sql[i + 1:j])
                    break
    return spans


def _probe_subquery_nulls(env, sql, budget):
    """Empty result + NOT IN/IN subquery: NULLs in the subquery silently kill rows."""
    notes = []
    spans = _subquery_spans(sql)
    if not spans:
        return notes, budget
    uses_not_in = re.search(r"\bnot\s+in\s*\(\s*select\b", sql, re.I) is not None
    for sub in spans[:2]:
        if budget <= 0:
            break
        probe = f"SELECT * FROM ({sub}) AS _sub LIMIT 50"
        r = _safe_execute(env, probe, max_rows=50)
        budget -= 1
        if not r.get("ok"):
            continue
        cols = r.get("columns", [])
        rows = r.get("rows", [])
        null_counts = []
        for idx, cname in enumerate(cols):
            n = sum(1 for row in rows if idx < len(row) and row[idx] is None)
            if n:
                null_counts.append(f"{cname}: {n} NULL(s) in first {len(rows)} rows")
        if null_counts:
            msg = (
                "- A subquery used by your query returns NULL values ("
                + "; ".join(null_counts)
                + "). In SQLite, `x NOT IN (subquery)` evaluates to NULL (never TRUE) for EVERY x "
                "as soon as the subquery contains even one NULL, so the outer query returns zero rows. "
                "Rewrite the exclusion with NOT EXISTS (correlated on the key) or add "
                "`WHERE key IS NOT NULL` inside the subquery."
            )
            notes.append(msg)
        elif uses_not_in:
            notes.append(
                "- Your query uses NOT IN with a subquery and returned zero rows. Verify the subquery "
                "covers every column/direction in which the relation can store the link, and prefer "
                "NOT EXISTS, which is safe against NULLs."
            )
    return notes, budget


def _projection_note(question, sql, schema):
    """Flag drafts that project only a name column for entity-level questions."""
    q = (question or "").lower()
    if not re.search(r"\b(which|what|show|find|list|give|who)\b", q):
        return None
    words = set(re.findall(r"[a-z]+", q))
    if words & ATTR_WORDS:
        return None
    if re.search(r"\bhow many\b|\bnumber of\b", q):
        return None
    m = re.match(r"(?is)\s*select\s+(.*?)\s+from\s", sql)
    if not m:
        return None
    sel = m.group(1).strip()
    if "*" in sel or "(" in sel:
        return None
    items = [p.strip() for p in sel.split(",") if p.strip()]
    if len(items) != 1:
        return None
    item = re.sub(r"(?i)^distinct\s+", "", items[0])
    item = re.sub(r"(?i)\s+as\s+[A-Za-z_0-9]+$", "", item).strip()
    colname = item.split(".")[-1].strip('`"[] ')
    if not NAMEISH.search(colname):
        return None
    aliases = _table_aliases(sql)
    tables = list(dict.fromkeys(aliases.values()))
    if len(tables) < 2:
        return None
    schema_cols = _schema_columns(schema)
    listing = []
    for tbl in tables:
        info = schema_cols.get(tbl.lower())
        if info:
            listing.append(f"{info[0]}({', '.join(info[1])})")
        else:
            listing.append(tbl)
    return (
        "- Projection scope looks too narrow: the question asks about entities themselves and does not "
        "name specific attributes, yet your query selects only the single column '" + colname + "'. "
        "For such questions the expected answer is usually the FULL rows of every table involved in the "
        "join (e.g. `SELECT T1.*, T2.*` with your existing aliases), not just a name column. "
        "Available columns: " + "; ".join(listing) + ". "
        "Widen the SELECT list accordingly unless the question clearly asks only for that one attribute."
    )


def _build_user(task, env, schema):
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    return user


def solve(task, env):
    cfg = env.config or {}
    schema = env.schema(task["db_id"])
    system = env.prompt("system_prompt.md")
    user = _build_user(task, env, schema)
    messages = [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=cfg.get("max_tokens", 800))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": "SELECT 1"}
    if not cfg.get("enable_repair", True):
        return {"sql": sql}

    result = _safe_execute(env, sql)
    ok = bool(result.get("ok"))
    nrows = result.get("n_rows", 0) or 0
    err = result.get("error") or ""

    notes = []
    budget = int(cfg.get("max_probes", 6))
    needs_repair = False

    if not ok:
        needs_repair = True
        notes.append(f"- Your query failed to execute. SQLite error: {err}")
    else:
        if nrows == 0:
            needs_repair = True
            notes.append("- Your query executed but returned ZERO rows. The question expects data, so a filter value, a join key or a condition is probably wrong.")
            nn, budget = _probe_subquery_nulls(env, sql, budget)
            notes.extend(nn)
            if cfg.get("probe_zero_row_joins", True):
                jn, budget = _probe_empty_join(env, sql, budget)
                notes.extend(jn)
        if cfg.get("probe_literals", True):
            vn, budget = _probe_values(env, sql, schema, budget)
            if vn:
                needs_repair = True
                notes.extend(vn)
        if cfg.get("check_projection_scope", True):
            pn = _projection_note(task.get("question", ""), sql, schema)
            if pn:
                needs_repair = True
                notes.append(pn)

    if not needs_repair:
        return {"sql": sql}

    preview = ""
    if ok and nrows:
        preview = (
            f"\nCurrent result columns: {result.get('columns')}\n"
            f"First rows: {result.get('rows', [])[:5]}\n"
        )

    repair_user = (
        user
        + "\n\nYour previous query was:\n```sql\n" + sql + "\n```\n"
        + preview
        + "\nDiagnostics from running it against the real database:\n"
        + "\n".join(notes)
        + "\n\nWrite a corrected query. Use the exact stored values shown above when they reveal a mismatch "
        "(casing, spacing, abbreviation); fix join keys using the schema's foreign keys; rewrite NULL-unsafe "
        "NOT IN subqueries with NOT EXISTS; and make sure the selected columns match exactly what the "
        "question asks for (full rows of ALL tables in the join when it asks for 'details'/all information "
        "or names entities without naming attributes). Keep everything that was already correct. "
        "Return only the final query in one ```sql block."
    )
    try:
        reply2 = env.chat(
            [
                {"role": "system", "content": system},
                {"role": "user", "content": repair_user},
            ],
            max_tokens=cfg.get("repair_max_tokens", 700),
        )
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    r2 = _safe_execute(env, sql2)
    if not r2.get("ok"):
        return {"sql": sql}
    if ok and nrows > 0 and (r2.get("n_rows", 0) or 0) == 0:
        return {"sql": sql}
    return {"sql": sql2}
